window.kbPageData["views/entry/k-d14505b87d3715af"] = {"key":"entry/k-d14505b87d3715af","state":{"route":"entry/k-d14505b87d3715af"},"node":{"id":"k-d14505b87d3715af","mode":"k","title":"经上级批准的行政行为如何确定被告","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["经上级批准的行政行为在未制作对外生效文书时按实际作出机关确定被告"],"qs":["江苏 2025 B类 行测#19"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"法条与类似裁判均已核实。仍需确认本题所指的被诉行为，以及排除县政府作为被告的依据。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：县自然资源和规划局并未制作回收决定书，也未通知该地块的使用权人","review":{"definition":"原题引文：县自然资源和规划局并未制作回收决定书，也未通知该地块的使用权人","explanation":"题中未另作收回决定书，确定被告须先识别韩某所诉的是县自然资源和规划局交付实施的行为，还是已因实际执行而对外产生效力的县政府批复。题给答案D采用前一种理解，将实施行为归于县自然资源和规划局。指导案例22号中，原告起诉的是县政府批复，法院认定批复实际执行后可诉，并指令继续审理。题中仅凭未制作收回决定书，尚不能确定应列哪个机关。","references":[{"source":"web-1eba6cf79110ba1f","location":"第二十六条第一款","quote":"作出行政行为的行政机关是被告"},{"source":"web-6af22ba7c0bedacd","location":"第十九条","quote":"以在对外发生法律效力的文书上署名的机关为被告"},{"source":"web-cbb6009c824299b2","location":"裁判理由","quote":"对该批复不服提起行政诉讼的，人民法院应当依法受理"}],"evidence":"县自然资源和规划局并未制作回收决定书，也未通知该地块的使用权人","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2025 B类 行测#19":{"paper":"江苏 2025 B类 行测","n":19,"mod":"常识判断","src":["91e0d9fd02ca7ec6d61f.pdf",5],"asrc":["f2ff67a0f2a2f7e8e926.pdf",8],"card":"6d0ae56d8045f83829848bad","links":[{"id":"k-d14505b87d3715af","role":"直接考查","why":"题设未制作对外生效的决定书，因此须根据实际作出收回行为的机关确定被告。"}]}},"terms":{},"references":{"web-1eba6cf79110ba1f":{"name":"《中华人民共和国行政诉讼法》","url":"https://ipc.court.gov.cn/zh-cn/news/view-396.html"},"web-6af22ba7c0bedacd":{"name":"《最高人民法院关于适用〈中华人民共和国行政诉讼法〉的解释》","url":"https://ipc.court.gov.cn/zh-cn/news/view-397.html"},"web-cbb6009c824299b2":{"name":"最高人民法院指导案例22号《魏永高、陈守志诉来安县人民政府收回土地使用权批复案》","url":"https://www.court.gov.cn/shenpan/xiangqing/6006.html"}},"topics":[],"units":{"k-d14505b87d3715af":[["江苏 2025 B类 行测#19"]]}};
